/**
 * @fileoverview Tests for concise-object rule
 * @author Jamund Ferguson <http://www.jamund.com>
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/object-shorthand"),
	RuleTester = require("../../../lib/rule-tester/rule-tester");
const { unIndent } = require("../../_utils");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const PROPERTY_ERROR = {
	messageId: "expectedPropertyShorthand",
};
const METHOD_ERROR = {
	messageId: "expectedMethodShorthand",
};
const LONGFORM_PROPERTY_ERROR = {
	messageId: "expectedPropertyLongform",
};
const LONGFORM_METHOD_ERROR = {
	messageId: "expectedMethodLongform",
};
const LONGFORM_METHOD_STRING_LITERAL_ERROR = {
	messageId: "expectedLiteralMethodLongform",
};
const ALL_SHORTHAND_ERROR = {
	messageId: "expectedAllPropertiesShorthanded",
};
const MIXED_SHORTHAND_ERROR = {
	messageId: "unexpectedMix",
};

const ruleTester = new RuleTester({ languageOptions: { ecmaVersion: 2018 } });

ruleTester.run("object-shorthand", rule, {
	valid: [
		"var x = {y() {}}",
		"var x = {y}",
		"var x = {a: b}",
		"var x = {a: 'a'}",
		"var x = {'a': 'a'}",
		"var x = {'a': b}",
		"var x = {y(x) {}}",
		"var {x,y,z} = x",
		"var {x: {y}} = z",
		"var x = {*x() {}}",
		"var x = {x: y}",
		"var x = {x: y, y: z}",
		"var x = {x: y, y: z, z: 'z'}",
		"var x = {x() {}, y: z, l(){}}",
		"var x = {x: y, y: z, a: b}",
		"var x = {x: y, y: z, 'a': b}",
		"var x = {x: y, y() {}, z: a}",
		"var x = {[y]: y}",
		"doSomething({x: y})",
		"doSomething({'x': y})",
		"doSomething({x: 'x'})",
		"doSomething({'x': 'x'})",
		"doSomething({y() {}})",
		"doSomething({x: y, y() {}})",
		"doSomething({y() {}, z: a})",
		"!{ a: function a(){} };",

		// arrow functions are still alright by default
		"var x = {y: (x)=>x}",
		"doSomething({y: (x)=>x})",
		"var x = {y: (x)=>x, y: a}",
		"doSomething({x, y: (x)=>x})",
		"({ foo: x => { return; }})",
		"({ foo: (x) => { return; }})",
		"({ foo: () => { return; }})",

		// getters and setters are ok
		"var x = {get y() {}}",
		"var x = {set y(z) {}}",
		"var x = {get y() {}, set y(z) {}}",
		"doSomething({get y() {}})",
		"doSomething({set y(z) {}})",
		"doSomething({get y() {}, set y(z) {}})",

		// object literal computed properties
		{
			code: "var x = {[y]: y}",
			options: ["properties"],
		},
		{
			code: "var x = {['y']: 'y'}",
			options: ["properties"],
		},
		{
			code: "var x = {['y']: y}",
			options: ["properties"],
		},

		// object literal computed methods
		{
			code: "var x = {[y]() {}}",
			options: ["methods"],
		},
		{
			code: "var x = {[y]: function x() {}}",
			options: ["methods"],
		},
		{
			code: "var x = {[y]: y}",
			options: ["methods"],
		},

		// options
		{
			code: "var x = {y() {}}",
			options: ["methods"],
		},
		{
			code: "var x = {x, y() {}, a:b}",
			options: ["methods"],
		},
		{
			code: "var x = {y}",
			options: ["properties"],
		},
		{
			code: "var x = {y: {b}}",
			options: ["properties"],
		},
		{
			code: "var x = {a: n, c: d, f: g}",
			options: ["never"],
		},
		{
			code: "var x = {a: function(){}, b: {c: d}}",
			options: ["never"],
		},

		// ignoreConstructors
		{
			code: "var x = {ConstructorFunction: function(){}, a: b}",
			options: ["always", { ignoreConstructors: true }],
		},
		{
			code: "var x = {_ConstructorFunction: function(){}, a: b}",
			options: ["always", { ignoreConstructors: true }],
		},
		{
			code: "var x = {$ConstructorFunction: function(){}, a: b}",
			options: ["always", { ignoreConstructors: true }],
		},
